    '<script>(function(){var list=document.querySelector("[data-live-list]"),status=document.querySelector("[data-live-status]"),busy=false;if(!list||!status)return;function load(){if(busy)return;busy=true;fetch("index.php?page=dashboard&live_page_views=1",{credentials:"same-origin",headers:{"Accept":"application/json"},cache:"no-store"}).then(function(response){if(!response.ok)throw new Error("โหลดข้อมูลไม่สำเร็จ");return response.json();}).then(function(data){if(!Array.isArray(data.views))throw new Error("รูปแบบข้อมูลไม่ถูกต้อง");list.replaceChildren();data.views.forEach(function(entry){if(!entry||typeof entry.path!=="string"||entry.path.charAt(0)!=="/")return;var target;try{target=new URL(entry.path,location.origin);}catch(error){return;}if(target.origin!==location.origin||target.search||target.hash)return;var item=document.createElement("li"),link=document.createElement("a"),details=document.createElement("div"),path=document.createElement("small"),time=document.createElement("time");link.href=target.href;link.textContent=typeof entry.title==="string"&&entry.title.trim()?entry.title:entry.path;link.title=entry.path;path.textContent=entry.path;details.appendChild(link);details.appendChild(path);item.appendChild(details);if(typeof entry.viewedAt==="string"){var date=new Date(entry.viewedAt.replace(" ","T"));if(!Number.isNaN(date.getTime())){time.dateTime=date.toISOString();time.textContent=new Intl.DateTimeFormat("th-TH",{hour:"2-digit",minute:"2-digit",second:"2-digit"}).format(date);item.appendChild(time);}}list.appendChild(item);});status.textContent=data.views.length?"อัปเดตอัตโนมัติทุก 10 วินาที · ล่าสุด "+data.views.length+" รายการ":"ยังไม่มีผู้เข้าชมหน้าเว็บ";}).catch(function(){status.textContent="ไม่สามารถโหลดข้อมูลผู้เข้าชมได้";}).finally(function(){busy=false;});}load();window.setInterval(load,10000);})();</script>' => '<script>(function(){var list=document.querySelector("[data-live-list]"),status=document.querySelector("[data-live-status]"),busy=false;if(!list||!status)return;function load(){if(busy)return;busy=true;fetch("index.php?page=dashboard&live_page_views=1",{credentials:"same-origin",headers:{"Accept":"application/json"},cache:"no-store"}).then(function(response){if(!response.ok)throw new Error("โหลดข้อมูลไม่สำเร็จ");return response.json();}).then(function(data){if(!Array.isArray(data.views))throw new Error("รูปแบบข้อมูลไม่ถูกต้อง");list.replaceChildren();data.views.forEach(function(entry){if(!entry||typeof entry.path!=="string"||entry.path.charAt(0)!=="/")return;var target;try{target=new URL(entry.path,location.origin);}catch(error){return;}if(target.origin!==location.origin||target.search||target.hash)return;var item=document.createElement("li"),link=document.createElement("a"),details=document.createElement("div"),path=document.createElement("small"),time=document.createElement("time");link.href=target.href;link.textContent=typeof entry.title==="string"&&entry.title.trim()?entry.title:entry.path;link.title=entry.path;path.textContent=entry.path;details.appendChild(link);details.appendChild(path);item.appendChild(details);if(typeof entry.viewedAt==="string"){var date=new Date(entry.viewedAt.replace(" ","T"));if(!Number.isNaN(date.getTime())){time.dateTime=date.toISOString();time.textContent=new Intl.DateTimeFormat("th-TH",{hour:"2-digit",minute:"2-digit",second:"2-digit"}).format(date);item.appendChild(time);}}list.appendChild(item);});status.textContent=data.views.length?"อัปเดตอัตโนมัติทุก 10 วินาที · ล่าสุด "+data.views.length+" รายการ":"ยังไม่มีผู้เข้าชมหน้าเว็บ";}).catch(function(){status.textContent="ไม่สามารถโหลดข้อมูลผู้เข้าชมได้";}).finally(function(){busy=false;});}load();window.setInterval(load,10000);})();</script>',
